# Генератор курса «HIDDEN DINOX — The Hidden Reaction System» для импорта в CMS (статус: черновик).
# Источник: книга «The Hidden Reaction System» v1.0 (HIDDENDINOX) и pattern.pdf. Номера страниц сверены с PDF.
import json, charts as K

def H(t): return {"type": "heading", "text": t}
def SRC(pages, extra=""): return {"type": "note", "variant": "source", "title": "Источник", "text": f"Книга «The Hidden Reaction System», {pages}." + (" " + extra if extra else "")}
def T(text, title=""): return {"type": "text", "title": title, "text": text}
def TERMS(items, title="Термины"): return {"type": "terms", "title": title, "items": [{"term": a, "definition": b} for a, b in items]}
def CH(c, role="illustration"): return {"type": "chart", "chart": c, "chart_role": role}
def NOTE(variant, text, title=""): return {"type": "note", "variant": variant, "title": title, "text": text}
def EX(title, text, chart=None): return {"type": "example", "title": title, "text": text, **({"chart": chart} if chart else {})}
def PR(task, criteria="", title="", homework=False, chart=None): return {"type": "practice", "title": title, "task": task, "criteria": criteria, "homework": homework, **({"chart": chart} if chart else {})}
def Q(qs, title="Контрольные вопросы", pass_percent=70, bid="quiz"): return {"type": "quiz", "id": bid, "title": title, "pass_percent": pass_percent, "questions": [{"q": q, "options": o, "correct": c, "explanation": e, "kind": k} for (q, o, c, e, k) in qs]}
def SUM(text): return {"type": "summary", "title": "Итог урока", "text": text}
def L(title, outcome, pages, blocks, quiz_required=True): return {"title": title, "outcome": outcome, "source_pages": f"книга, {pages}", "pass_criteria": {"require_quiz": quiz_required, "min_percent": 70}, "blocks": blocks}

full_b, full_anns, _ = K.cycle_reversal_up(11)
FULL = K.chart(full_b, full_anns, "Четыре этапа подготовки рынка", K.CAP + " Направление реакции здесь — как на авторской схеме Hidden Reversal.")
entry_b, entry_anns, _ = K.cycle_reversal_up(11, entry=True)
ENTRY = K.chart(entry_b, entry_anns, "Где появляется точка входа", K.CAP)
PRACTICE_CYCLE = K.chart(*K.cycle_breakdown_down(61), "Найдите четыре этапа", "Учебная схема для самостоятельной разметки, синтетические данные.")

RISK = NOTE("risk", "Курс — образовательный. Это не торговый сигнал и не инвестиционная рекомендация. В книге прямо сказано: «Не каждая сделка будет прибыльной. Убытки — это часть трейдинга». Все графики курса — учебные схемы на синтетических данных, а не реальные котировки.", "Риск")

