    TERMS([("Импульс", "Сильное движение цены — та часть, которую замечает большинство (по книге — «финальная часть»)."), ("Hidden Reaction", "По определению автора — «система, которая позволяет увидеть подготовку рынка ДО движения» (стр. 3)."), ("Подготовка рынка", "Этапы, через которые, по книге, рынок проходит перед импульсом.")]),
